contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address other, uint depositAmt, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(other != address(this), "other must differ from caller");
        require(address(this).balance >= depositAmt, "insufficient balance");

        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        uint otherBefore = c.balances(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint otherAfter = c.balances(other); if (__ESBMC_reverted()) return;

        assert(otherAfter == otherBefore);
    }
}

